mapper.sql:
WHERE q.deleted = 0 AND q.status = 1 AND c.status = 1
AND q.category_id = #{query.categoryId}
AND q.difficulty = #{query.difficulty}
AND EXISTS (SELECT 1 FROM question_tag qt WHERE qt.question_id = q.id AND qt.tag_id = #{query.tagId})
AND (q.title LIKE CONCAT('%', #{query.keyword}, '%') ESCAPE '\\' OR EXISTS (SELECT 1 FROM question_tag qt2 JOIN tag t ON t.id = qt2.tag_id WHERE qt2.question_id = q.id AND t.name LIKE CONCAT('%', #{query.keyword}, '%') ESCAPE '\\'))

mapper.select:
SELECT qt.question_id, t.id AS tag_id, t.name AS tag_name FROM question_tag qt JOIN tag t ON t.id = qt.tag_id WHERE qt.question_id IN
#{id}
ORDER BY qt.question_id ASC, t.id ASC
